<?php
use App\Core\{Csrf,DataTableFormat};
use App\Services\ArpaAppointmentIssuePresentation;
$baseline=$request['baseline'];$source=$baseline['source_correction'];$actions=$request['interface_actions'];$context=$request['display_context'];
$related=$baseline['related_write_set']['appointments']??[$baseline['appointment']];$relatedRequests=[];$relatedClosures=[];
foreach(($baseline['related_write_set']['requests']??[]) as $row)$relatedRequests[(string)$row['id']]=$row;
foreach(($baseline['related_write_set']['closures']??[]) as $row)$relatedClosures[(string)$row['appointment_id']]=$row;
$proposalLabels=$context['proposal_labels']??[];
$displayProposal=static function(string $key,mixed $value)use($proposalLabels):string{
    if($value===null||$value==='')return '—';
    if(isset($proposalLabels[$key]))return (string)$proposalLabels[$key];
    if($key==='appointment_id')return 'Canonical appointment '.substr((string)$value,0,8);
    return DataTableFormat::enumLabel((string)$value,(string)$value);
};
$status=(string)$request['workflow_status'];$editable=in_array($status,['DRAFT','RETURNED'],true);
?>
<div class="page-heading"><div><div class="breadcrumb-lite">ARPA Officer Assignments / Correction Amendment</div><h1>Correction Amendment</h1><p>Governed proposal, affected records, and append-only review history.</p></div><?= DataTableFormat::badge($status) ?></div>
<?php if($editable): ?><div class="alert alert-warning"><strong>This proposal has not changed the appointment.</strong> <?= $status==='RETURNED'?'Correct the returned proposal and resubmit it.':'Submit it to begin the ASC, District, and National review sequence.' ?></div><?php elseif($status==='NATIONAL_APPROVED'): ?><div class="alert alert-success"><strong>This amendment was finally approved and applied.</strong> The original correction remains in the audit history.</div><?php else: ?><div class="alert alert-info"><strong>This proposal is in the approval workflow.</strong> No appointment change is applied before final National approval.</div><?php endif; ?>
<div class="row g-3 mb-4">
<div class="col-lg-6"><div class="form-section h-100"><h2 class="h5">Original Decision</h2><dl class="row mb-0">
<dt class="col-sm-5">Source Reference</dt><dd class="col-sm-7"><a href="<?= e(url('hr/arpa-appointments/issues/corrections/'.$request['source_correction_id'])) ?>"><?= e(substr((string)$request['source_correction_id'],0,8)) ?></a></dd>
<dt class="col-sm-5">Issue</dt><dd class="col-sm-7"><?= e(DataTableFormat::enumLabel($source['issue_type'],'—')) ?></dd><dt class="col-sm-5">Decision</dt><dd class="col-sm-7"><?= e(ArpaAppointmentIssuePresentation::action($source['correction_action'])) ?></dd><dt class="col-sm-5">Decision Status</dt><dd class="col-sm-7"><?= DataTableFormat::badge($source['resolution_status']) ?></dd><dt class="col-sm-5">Original Reason</dt><dd class="col-sm-7"><?= e($source['correction_reason']) ?></dd><dt class="col-sm-5">Officer</dt><dd class="col-sm-7"><?= e(($context['officer_number']??'').' - '.($context['officer_name']??'')) ?></dd><dt class="col-sm-5">ASC</dt><dd class="col-sm-7"><?= e(($context['asc_number']??'').' - '.($context['asc_name']??'')) ?></dd>
</dl></div></div>
<div class="col-lg-6"><div class="form-section h-100"><h2 class="h5">Proposed Change</h2><dl class="row mb-0">
<dt class="col-sm-5">Action</dt><dd class="col-sm-7"><?= e(ArpaAppointmentIssuePresentation::action($request['proposed_action'])) ?></dd><?php foreach($request['proposed'] as $key=>$value): ?><dt class="col-sm-5"><?= e(DataTableFormat::enumLabel((string)$key)) ?></dt><dd class="col-sm-7"><?= e($displayProposal((string)$key,$value)) ?></dd><?php endforeach; ?><dt class="col-sm-5">Reason</dt><dd class="col-sm-7"><?= e($request['correction_reason']) ?></dd><dt class="col-sm-5">Remarks</dt><dd class="col-sm-7"><?= nl2br(e($request['remarks']?:'—')) ?></dd><dt class="col-sm-5">Evidence</dt><dd class="col-sm-7"><?= e($request['evidence_reference']?:'—') ?></dd><?php if($request['applied_correction_id']): ?><dt class="col-sm-5">Applied Correction</dt><dd class="col-sm-7"><a href="<?= e(url('hr/arpa-appointments/issues/corrections/'.$request['applied_correction_id'])) ?>"><?= e(substr((string)$request['applied_correction_id'],0,8)) ?></a></dd><?php endif; ?>
</dl></div></div></div>
<div class="card mb-4"><div class="card-body"><h2 class="h5">Complete Affected Appointment Set</h2><p class="small text-muted">These exact records are frozen in the proposal baseline and revalidated before final approval.</p><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Appointment</th><th>Type</th><th>ARPA Division</th><th>Effective From</th><th>Effective To</th><th>Request Status</th><th>Origin</th></tr></thead><tbody>
<?php foreach($related as $row):$linked=$relatedRequests[(string)$row['request_id']]??[];$linkedClosure=$relatedClosures[(string)$row['id']]??null; ?><tr><td><?= e(substr((string)$row['id'],0,8)) ?></td><td><?= e(DataTableFormat::enumLabel($row['appointment_type'])) ?></td><td><?= e(($row['arpa_dad_snapshot']??'').' - '.($row['arpa_name_snapshot']??'')) ?></td><td><?= DataTableFormat::date($row['effective_from']) ?></td><td><?= DataTableFormat::date($linkedClosure['effective_to']??null,'Open') ?></td><td><?= DataTableFormat::badge($linked['workflow_status']??'UNKNOWN') ?></td><td><?= DataTableFormat::badge($row['record_origin']) ?></td></tr><?php endforeach; ?>
</tbody></table></div></div></div>
<?php if($actions['edit']||$actions['withdraw']||$actions['submit']): ?><div class="d-flex flex-wrap gap-2 mb-4">
<?php if($actions['edit']): ?><a class="btn btn-primary" href="<?= e(url('hr/arpa-appointments/correction-amendments/'.$request['id'].'/edit')) ?>">Edit Proposal</a><?php endif; ?>
<?php if($actions['submit']): ?><form method="post" action="<?= e(url('hr/arpa-appointments/correction-amendments/'.$request['id'].'/submit')) ?>"><?= Csrf::field() ?><input type="hidden" name="version" value="<?= e((string)$request['version']) ?>"><button class="btn btn-success" type="submit"><?= e((string)$actions['submit_label']) ?></button></form><?php endif; ?>
<?php if($actions['withdraw']): ?><form class="d-flex gap-2" method="post" action="<?= e(url('hr/arpa-appointments/correction-amendments/'.$request['id'].'/withdraw')) ?>"><?= Csrf::field() ?><input type="hidden" name="version" value="<?= e((string)$request['version']) ?>"><input class="form-control" name="comments" maxlength="1000" placeholder="Withdrawal note (optional)"><button class="btn btn-outline-danger" type="submit">Withdraw</button></form><?php endif; ?>
</div><?php endif; ?>
<?php if($actions['primary_review']||$actions['return']||$actions['reject']): ?><div class="card border-primary mb-4"><div class="card-body"><h2 class="h5">Review Action</h2><?php if($actions['final_approval']): ?><div class="alert alert-danger"><strong>Final National approval applies the displayed correction.</strong> DEMS revalidates the complete baseline and applies it transactionally.</div><?php endif; ?><div class="d-flex flex-wrap gap-3 align-items-start">
<?php if($actions['primary_review']): ?><form method="post" action="<?= e(url('hr/arpa-appointments/correction-amendments/'.$request['id'].'/review')) ?>"><?= Csrf::field() ?><input type="hidden" name="version" value="<?= e((string)$request['version']) ?>"><input type="hidden" name="action" value="<?= e($actions['primary_review']['action']) ?>"><?php if($actions['final_approval']): ?><div class="form-check mb-2"><input class="form-check-input" id="confirm-apply" type="checkbox" name="confirm_apply" value="1" required><label class="form-check-label" for="confirm-apply">I confirm final approval may apply this correction.</label></div><?php endif; ?><button class="btn btn-success" type="submit"><?= e($actions['primary_review']['label']) ?></button></form><?php endif; ?>
<?php if($actions['return']): ?><form class="d-flex gap-2" method="post" action="<?= e(url('hr/arpa-appointments/correction-amendments/'.$request['id'].'/review')) ?>"><?= Csrf::field() ?><input type="hidden" name="version" value="<?= e((string)$request['version']) ?>"><input type="hidden" name="action" value="RETURN_FOR_CORRECTION"><input class="form-control" name="reason" maxlength="1000" required placeholder="Reason for return"><button class="btn btn-outline-warning text-dark" type="submit">Return for Correction</button></form><?php endif; ?>
<?php if($actions['reject']): ?><form class="d-flex gap-2" method="post" action="<?= e(url('hr/arpa-appointments/correction-amendments/'.$request['id'].'/review')) ?>"><?= Csrf::field() ?><input type="hidden" name="version" value="<?= e((string)$request['version']) ?>"><input type="hidden" name="action" value="REJECT"><input class="form-control" name="reason" maxlength="1000" required placeholder="Reason for rejection"><button class="btn btn-outline-danger" type="submit">Reject</button></form><?php endif; ?>
</div></div></div><?php endif; ?>
<div class="card mb-4"><div class="card-body"><h2 class="h5">Workflow and Event History</h2><p class="small text-muted">Historical actions remain for audit. Only rows marked Current cycle belong to the present submission cycle.</p><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Cycle</th><th>Action</th><th>Stage</th><th>Status Change</th><th>Performed By</th><th>Comments</th><th>Action At</th></tr></thead><tbody><?php foreach($request['events'] as $event): ?><tr><td><?= $event['current_cycle']?'<span class="badge bg-primary">Current cycle</span>':'<span class="badge bg-secondary">Earlier cycle</span>' ?></td><td><?= e(DataTableFormat::enumLabel($event['action'])) ?></td><td><?= e(DataTableFormat::enumLabel($event['stage'])) ?></td><td><?= e(DataTableFormat::enumLabel($event['previous_status'],'New').' → '.DataTableFormat::enumLabel($event['new_status'])) ?></td><td><?= e($event['performed_by']) ?></td><td><?= e($event['comments']?:'—') ?></td><td><?= DataTableFormat::dateTime($event['action_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
